// `Env` (the DB binding) is generated by `wrangler types` from wrangler.jsonc.
// JWT_SECRET is a secret, so it is declared here rather than in the config file.
export type Bindings = Env & { JWT_SECRET: string };

export type AppEnv = {
  Bindings: Bindings;
  // Set by authMiddleware (the Express version used req.userid).
  Variables: { userid: string };
};
